"""
TEN VAD speech islands for VAD-owned timing (VAD-only).

TEN / WhisperSeg speech segments supply the usual VAD source. For
anime-whisper the engine prefers **per-frame ASR** (decode each short VAD
group, default ≤5s / 0.5s silence) so the frame boundary owns the timeline.
``align_cues_ten_vad`` remains as a proportional-mapping fallback when
island ASR is unavailable.
"""

from __future__ import annotations

import logging
import os
import subprocess
from pathlib import Path
from typing import Any

import numpy as np

_log = logging.getLogger("transub_engine.vad.ten_vad_seg")

SAMPLE_RATE = 16000
_HOP = 256  # 16 ms @ 16 kHz
_DEFAULT_THRESHOLD = 0.45  # slightly more recall for soft / breathy JA

# libsndfile / soundfile cannot open most video containers (mp4/mkv/…).
_SOUNDFILE_EXTS = frozenset(
    {".wav", ".flac", ".ogg", ".oga", ".opus", ".aiff", ".aif", ".au", ".raw", ".w64"}
)


def ten_vad_available() -> bool:
    try:
        from ten_vad import TenVad  # noqa: F401

        return True
    except Exception:
        return False


def _float32_to_int16(audio: np.ndarray) -> np.ndarray:
    audio = np.asarray(audio, dtype=np.float32)
    if getattr(audio, "ndim", 1) > 1:
        audio = np.mean(audio, axis=-1)
    return (np.clip(audio, -1.0, 1.0) * 32767.0).astype(np.int16)


def _load_mono_16k_ffmpeg(
    path: str,
    *,
    max_media_s: float | None = None,
) -> np.ndarray:
    """Decode any ffmpeg-readable media to mono float32 @ 16 kHz."""
    from ..ffmpeg_util import resolve_ffmpeg

    ffmpeg = resolve_ffmpeg()
    if not ffmpeg:
        raise RuntimeError("ffmpeg not found; cannot decode audio for TEN VAD")
    cmd = [
        ffmpeg,
        "-hide_banner",
        "-loglevel",
        "error",
        "-i",
        path,
    ]
    if max_media_s is not None and float(max_media_s) > 0:
        cmd.extend(["-t", f"{float(max_media_s):.3f}"])
    cmd.extend(
        [
            "-ac",
            "1",
            "-ar",
            str(SAMPLE_RATE),
            "-f",
            "f32le",
            "-acodec",
            "pcm_f32le",
            "pipe:1",
        ]
    )
    run_kw: dict[str, Any] = {
        "capture_output": True,
        "check": False,
        "timeout": 600,
    }
    if os.name == "nt":
        run_kw["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    try:
        proc = subprocess.run(cmd, **run_kw)
    except subprocess.TimeoutExpired as err:
        raise RuntimeError(f"ffmpeg decode timed out for TEN VAD: {path}") from err
    if proc.returncode != 0:
        err = (proc.stderr or b"").decode("utf-8", errors="replace")[:800]
        raise RuntimeError(f"ffmpeg decode failed for TEN VAD: {err}")
    if not proc.stdout:
        return np.zeros(0, dtype=np.float32)
    return np.frombuffer(proc.stdout, dtype=np.float32).copy()


def _load_mono_soundfile(path: str) -> np.ndarray:
    import soundfile as sf

    audio, sr = sf.read(path, dtype="float32", always_2d=False)
    if getattr(audio, "ndim", 1) > 1:
        audio = np.mean(audio, axis=-1)
    audio = np.asarray(audio, dtype=np.float32)
    if int(sr) != SAMPLE_RATE:
        try:
            import librosa

            audio = librosa.resample(audio, orig_sr=int(sr), target_sr=SAMPLE_RATE)
        except Exception:
            duration = len(audio) / float(sr) if sr else 0.0
            n = max(1, int(round(duration * SAMPLE_RATE)))
            x_old = np.linspace(0.0, 1.0, num=len(audio), endpoint=False)
            x_new = np.linspace(0.0, 1.0, num=n, endpoint=False)
            audio = np.interp(x_new, x_old, audio).astype(np.float32)
    return audio


def _load_float32_mono_16k(
    path: str,
    *,
    max_media_s: float | None = None,
) -> np.ndarray:
    """
    Load media as mono float32 @ 16 kHz.

    Video containers (mp4/mkv/…) must go through ffmpeg — soundfile/libsndfile
    raises ``Format not recognised``. WAV/FLAC prefer soundfile when present.
    """
    ext = Path(path).suffix.lower()
    prefer_sf = ext in _SOUNDFILE_EXTS
    errors: list[str] = []
    name = Path(path).name

    def _clip(audio: np.ndarray) -> np.ndarray:
        audio = np.asarray(audio, dtype=np.float32)
        if getattr(audio, "ndim", 1) > 1:
            audio = np.mean(audio, axis=-1).astype(np.float32)
        if max_media_s is not None and max_media_s > 0:
            audio = audio[: int(float(max_media_s) * SAMPLE_RATE)]
        return audio

    if prefer_sf:
        try:
            audio = _clip(_load_mono_soundfile(path))
            _log.info(
                "TEN VAD decode: soundfile | %s | %.1fs @ %d Hz",
                name,
                len(audio) / float(SAMPLE_RATE),
                SAMPLE_RATE,
            )
            return audio
        except Exception as err:
            errors.append(f"soundfile: {err}")
            _log.info(
                "TEN VAD soundfile failed for %s (%s); trying ffmpeg",
                name,
                err,
            )

    try:
        _log.info(
            "TEN VAD decode: ffmpeg | %s%s",
            name,
            f" | max {float(max_media_s):.0f}s"
            if max_media_s is not None and float(max_media_s) > 0
            else "",
        )
        audio = _clip(_load_mono_16k_ffmpeg(path, max_media_s=max_media_s))
        _log.info(
            "TEN VAD decode ok: ffmpeg | %s | %.1fs @ %d Hz",
            name,
            len(audio) / float(SAMPLE_RATE),
            SAMPLE_RATE,
        )
        return audio
    except Exception as err:
        errors.append(f"ffmpeg: {err}")
        _log.warning("TEN VAD ffmpeg decode failed for %s: %s", name, err)

    if not prefer_sf:
        try:
            audio = _clip(_load_mono_soundfile(path))
            _log.info(
                "TEN VAD decode: soundfile fallback | %s | %.1fs",
                name,
                len(audio) / float(SAMPLE_RATE),
            )
            return audio
        except Exception as err:
            errors.append(f"soundfile: {err}")

    raise RuntimeError(
        "TEN VAD could not decode audio from "
        f"{path!r} ({'; '.join(errors) or 'no decoder'})"
    )


def _load_int16_mono_16k(
    path: str,
    *,
    max_media_s: float | None = None,
) -> np.ndarray:
    """Load media as int16 mono @ 16 kHz for TenVad.process."""
    return _float32_to_int16(_load_float32_mono_16k(path, max_media_s=max_media_s))


def slice_pcm_f32(
    audio: np.ndarray,
    start_s: float,
    end_s: float,
    *,
    sample_rate: int = SAMPLE_RATE,
) -> np.ndarray:
    """Slice mono float32 PCM by wall-clock seconds (same clock as TEN intervals)."""
    pcm = np.asarray(audio, dtype=np.float32)
    if getattr(pcm, "ndim", 1) > 1:
        pcm = np.mean(pcm, axis=-1).astype(np.float32)
    sr = max(1, int(sample_rate))
    i0 = max(0, int(float(start_s) * sr))
    i1 = min(len(pcm), max(i0 + 1, int(float(end_s) * sr)))
    return pcm[i0:i1].copy()


def _run_ten_vad_on_int16(
    audio_i16: np.ndarray,
    *,
    threshold: float,
    hop_size: int,
    min_speech_s: float,
    merge_gap_s: float,
    pad_s: float,
    name: str,
) -> list[tuple[float, float]]:
    from ten_vad import TenVad

    hop = max(64, int(hop_size))
    vad = TenVad(hop, float(threshold))
    n_frames = len(audio_i16) // hop
    if n_frames <= 0:
        _log.info("TEN VAD collect: empty audio for %s", name)
        return []

    flags: list[int] = []
    for i in range(n_frames):
        frame = audio_i16[i * hop : (i + 1) * hop]
        _prob, flag = vad.process(frame)
        flags.append(int(flag))

    raw: list[list[float]] = []
    cur: list[float] | None = None
    for i, flag in enumerate(flags):
        t0 = i * hop / float(SAMPLE_RATE)
        t1 = (i + 1) * hop / float(SAMPLE_RATE)
        if flag:
            if cur is None:
                cur = [t0, t1]
            else:
                cur[1] = t1
        elif cur is not None:
            raw.append(cur)
            cur = None
    if cur is not None:
        raw.append(cur)

    filtered = [[s, e] for s, e in raw if (e - s) >= float(min_speech_s)]
    merged: list[list[float]] = []
    gap = float(merge_gap_s)
    for s, e in filtered:
        if merged and s <= merged[-1][1] + gap:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])

    pad = max(0.0, float(pad_s))
    audio_end = len(audio_i16) / float(SAMPLE_RATE)
    out: list[tuple[float, float]] = []
    for s, e in merged:
        s2 = max(0.0, s - pad)
        e2 = min(audio_end, e + pad)
        if e2 - s2 >= float(min_speech_s):
            out.append((s2, e2))

    spoken = sum(e - s for s, e in out)
    _log.info(
        "TEN VAD collect done: %s | audio=%.1fs | raw=%d | merged=%d | spoken=%.1fs "
        "(%.0f%%) | first=%s | last=%s",
        name,
        audio_end,
        len(raw),
        len(out),
        spoken,
        (100.0 * spoken / audio_end) if audio_end > 0 else 0.0,
        f"{out[0][0]:.1f}-{out[0][1]:.1f}s" if out else "-",
        f"{out[-1][0]:.1f}-{out[-1][1]:.1f}s" if out else "-",
    )
    return out


def collect_ten_vad_intervals_with_audio(
    media_path: str,
    *,
    threshold: float = _DEFAULT_THRESHOLD,
    hop_size: int = _HOP,
    min_speech_s: float = 0.18,
    merge_gap_s: float = 0.4,
    pad_s: float = 0.08,
    max_media_s: float | None = None,
) -> tuple[list[tuple[float, float]], np.ndarray]:
    """
    Run TEN VAD and return ``(intervals, audio_f32)``.

    ``audio_f32`` is mono float32 @ 16 kHz on the same clock as interval
    bounds — callers can slice it for island ASR without re-decoding.
    """
    name = Path(media_path).name
    _log.info(
        "TEN VAD collect start: %s | threshold=%.2f | merge_gap=%.2fs | min_speech=%.2fs%s",
        name,
        float(threshold),
        float(merge_gap_s),
        float(min_speech_s),
        f" | max_media={float(max_media_s):.0f}s"
        if max_media_s is not None and float(max_media_s) > 0
        else "",
    )
    audio_f32 = _load_float32_mono_16k(media_path, max_media_s=max_media_s)
    audio_i16 = _float32_to_int16(audio_f32)
    intervals = _run_ten_vad_on_int16(
        audio_i16,
        threshold=threshold,
        hop_size=hop_size,
        min_speech_s=min_speech_s,
        merge_gap_s=merge_gap_s,
        pad_s=pad_s,
        name=name,
    )
    mb = (len(audio_f32) * 4) / (1024.0 * 1024.0)
    _log.info(
        "TEN VAD PCM ready for island ASR | samples=%d | ~%.1f MB | reuse=yes",
        len(audio_f32),
        mb,
    )
    return intervals, audio_f32


def collect_ten_vad_intervals(
    media_path: str,
    *,
    threshold: float = _DEFAULT_THRESHOLD,
    hop_size: int = _HOP,
    min_speech_s: float = 0.18,
    merge_gap_s: float = 0.4,
    pad_s: float = 0.08,
    max_media_s: float | None = None,
) -> list[tuple[float, float]]:
    """
    Run TEN VAD over ``media_path`` and return merged speech [start, end] pairs.
    """
    intervals, _audio = collect_ten_vad_intervals_with_audio(
        media_path,
        threshold=threshold,
        hop_size=hop_size,
        min_speech_s=min_speech_s,
        merge_gap_s=merge_gap_s,
        pad_s=pad_s,
        max_media_s=max_media_s,
    )
    return intervals


def intervals_as_timing_cues(
    intervals: list[tuple[float, float]],
) -> list[dict[str, Any]]:
    """Wrap VAD intervals as timing-cue dicts for ``align_text_cues_to_timing``."""
    cues: list[dict[str, Any]] = []
    for s, e in intervals:
        if e <= s:
            continue
        cues.append({"start": float(s), "end": float(e), "text": "speech"})
    return cues


def align_cues_ten_vad(
    text_cues: list[dict[str, Any]] | None,
    *,
    media_path: str,
    threshold: float = _DEFAULT_THRESHOLD,
    media_end_s: float | None = None,
) -> list[dict[str, Any]] | None:
    """
    VAD-only timing: TEN speech islands + anime text mapping.

    Returns aligned cues, or ``None`` when TEN is unavailable / finds no speech
    (caller should fall back to ASR timing).
    """
    if not text_cues:
        return []
    if not ten_vad_available():
        return None
    try:
        intervals = collect_ten_vad_intervals(
            media_path,
            threshold=threshold,
            max_media_s=media_end_s,
        )
        if not intervals:
            _log.info("TEN VAD found no speech islands on %s", media_path)
            return None
        from ..asr.whisper_fw import align_text_cues_to_timing

        timing = intervals_as_timing_cues(intervals)
        return align_text_cues_to_timing(text_cues, timing)
    except Exception as err:
        _log.warning("TEN VAD timing failed: %s", err)
        return None
